def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.
    """
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}
    abridores = set(pares.values())

    for char in s:
        if char in abridores:
            pila.append(char)
        elif char in pares:
            if not pila or pila[-1] != pares[char]:
                return False
            pila.pop()

    return not pila

def mediana(nums):
    if not nums:
        return None
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    if n % 2 == 0:
        return (nums_sorted[n // 2 - 1] + nums_sorted[n // 2]) / 2
    else:
        return nums_sorted[n // 2]

