def anidar(plano: dict) -> dict:
    def _anidar(d: dict, prefix: str = "") -> dict:
        resultado = {}
        for clave, valor in d.items():
            if "." in clave:
                partes = clave.split(".")
                nuevo_prefixo = prefix + partes[0]
                resultado[nuevo_prefixo] = _anidar({partes[1]: valor}, nuevo_prefixo)
            else:
                if prefix:
                    resultado[prefix] = {clave: valor}
                else:
                    resultado[clave] = valor
        return resultado

    return _anidar(plano)

