def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    filas = len(grid)
    columnas = len(grid[0])
    islas = 0

    def bfs(fila, columna):
        queue = [(fila, columna)]
        grid[fila][columna] = 0

        while queue:
            actual_fila, actual_columna = queue.pop(0)

            for delta_fila, delta_columna in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nueva_fila = actual_fila + delta_fila
                nueva_columna = actual_columna + delta_columna

                if (0 <= nueva_fila < filas and
                    0 <= nueva_columna < columnas and
                    grid[nueva_fila][nueva_columna] == 1):
                    grid[nueva_fila][nueva_columna] = 0
                    queue.append((nueva_fila, nueva_columna))

    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1:
                islas += 1
                bfs(i, j)

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # borrado
                    dp[i][j - 1],    # inserción
                    dp[i - 1][j - 1] # sustitución
                )
    return dp[m][n]

import re

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not re.search(r'[A-Z]', p):
        return False
    if not re.search(r'[a-z]', p):
        return False
    if not re.search(r'[0-9]', p):
        return False
    if not re.search(r'[^A-Za-z0-9]', p):
        return False
    return True

